#ifndef XEXMAGIC_IMPORT_NAMES_H_
#define XEXMAGIC_IMPORT_NAMES_H_

#include <cstdint>
#include <map>
#include <string>
#include <vector>

struct ImportLibrary;

// Resolves a call target to a kernel import name.
//
// A XEX imports purely by ordinal - the names exist nowhere in the file - so
// the mapping comes from a baked-in copy of Nexia's export tables
// (src/kernel_ordinals.inc, regenerated by tools/gen_kernel_ordinals.py).
//
// Two address spaces matter per import: the THUNK, which is what a `bl`
// targets, and the VALUE slot holding the resolved pointer, which is what an
// indirect call loads from. Both are recorded so either style of call site
// resolves.
class ImportNameTable {
 public:
  // Builds from the XEX's import libraries. Library names are matched loosely
  // ("xam.xex" -> xam, "xboxkrnl.exe" -> xboxkrnl) since casing varies.
  void Build(const std::vector<ImportLibrary>& libraries);

  bool empty() const { return thunks_.empty() && values_.empty(); }

  // Name for a branch target, or nullptr. Includes the module so an unnamed
  // ordinal still reads as e.g. "xam_ordinal_1234".
  const char* LookupThunk(uint32_t address) const;

  // Name for the address an indirect call loaded its pointer from.
  const char* LookupValue(uint32_t address) const;

  // Either, preferring the thunk. Convenient when a caller does not know which
  // form it is looking at.
  const char* Lookup(uint32_t address) const;

  size_t size() const { return thunks_.size(); }

 private:
  std::map<uint32_t, std::string> thunks_;
  std::map<uint32_t, std::string> values_;
};

// Name for a (module, ordinal) pair straight from the baked table, or nullptr
// when the ordinal is not known. Module is "xam" or "xboxkrnl".
const char* LookupKernelOrdinal(const char* module, uint32_t ordinal);

// One entry of the baked tables.
struct KernelExport {
  const char* module;
  uint32_t ordinal;
  const char* name;
};

// Every known kernel/xam export, whether or not the open image imports it.
// The tables are complete, so a name can be searched for before knowing which
// ordinal - or whether this title uses it at all.
const std::vector<KernelExport>& AllKernelExports();

#endif  // XEXMAGIC_IMPORT_NAMES_H_
